{"function":"() => {
const q=s=>[...document.querySelectorAll(s)];
const r=e=>{const b=e.getBoundingClientRect();return [Math.round(b.x),Math.round(b.y),Math.round(b.width),Math.round(b.height)]};
const cs=(e,p)=>{const c=getComputedStyle(e);return p.map(k=>c[k]).join(' | ')};
const out={};
out.lang=document.documentElement.lang;
out.labels=q('label,legend,.apoio-solicitacao,.text-base,.upload-button,button,th,td,.table-title,.crumb a,.crumb span,.marca-govbr,h1,h2').map(e=>e.className+':'+e.textContent.trim().slice(0,20)+' '+cs(e,['color','backgroundColor','fontSize','opacity'])+' '+r(e));
out.inputs=q('input,textarea,button').map(e=>(e.id||e.className)+' '+e.type+' '+r(e)+' '+cs(e,['outlineStyle','outlineWidth','borderColor','opacity','display','position']));
out.radios=q('.br-radio,.br-checkbox').map(e=>e.textContent.trim().slice(0,15)+' '+r(e)+' '+r(e.querySelector('input'))+' '+r(e.querySelector('label')));
return out}"}

